define('_JEXEC', 1);
define('JPATH_BASE', getcwd() . '/administrator');
// The playground's own defines.php registers its database driver.
if (is_file(JPATH_BASE . '/defines.php')) {
    include_once JPATH_BASE . '/defines.php';
}
if (!defined('_JDEFINES')) {
    require_once JPATH_BASE . '/includes/defines.php';
}
require_once JPATH_BASE . '/includes/framework.php';
$db = \Joomla\CMS\Factory::getContainer()->get(\Joomla\Database\DatabaseInterface::class);
// Without an application: Factory::getDate() and Joomla's Table classes need one.
$now = gmdate('Y-m-d H:i:s');
$user = (int) $db->setQuery('SELECT MIN(user_id) FROM #__user_usergroup_map WHERE group_id = 8')->loadResult();

$id = function ($table, $alias, $where = '') use ($db) {
    $found = $db->setQuery('SELECT id FROM ' . $table . ' WHERE alias = ' . $db->quote($alias) . $where . ' ORDER BY id LIMIT 1')->loadResult();
    if (!$found) {
        throw new RuntimeException("Not found in $table: $alias");
    }
    return (int) $found;
};

$insert = function ($table, $row) use ($db) {
    $query = $db->getQuery(true)->insert($table)->columns(array_map([$db, 'quoteName'], array_keys($row)))
        ->values(implode(',', array_map(fn ($value) => $value === null ? 'NULL' : $db->quote($value), $row)));
    $db->setQuery($query)->execute();
    return (int) $db->insertid();
};

// The nested set of a table (lft, rgt, level and path), from parent_id; new rows (lft 0) go after their siblings.
$rebuild = function ($table, $parent = 1, $left = 0, $level = 0, $path = '') use ($db, &$rebuild) {
    $right = $left + 1;
    $children = $db->setQuery('SELECT id, alias FROM ' . $table . ' WHERE parent_id = ' . (int) $parent . ' ORDER BY lft = 0, lft, id')->loadObjectList();
    foreach ($children as $child) {
        $right = $rebuild($table, $child->id, $right, $level + 1, ltrim($path . '/' . $child->alias, '/'));
    }
    $db->setQuery('UPDATE ' . $table . ' SET lft = ' . $left . ', rgt = ' . $right . ', level = ' . $level . ', path = ' . $db->quote($path) . ' WHERE id = ' . (int) $parent)->execute();
    return $right + 1;
};

$addCategory = function ($title, $alias, $parent, $published, $access, $language, $description) use ($db, $id, $insert, $rebuild, $now, $user) {
    $insert('#__categories', [
        'parent_id' => $parent ? $id('#__categories', $parent, " AND extension = 'com_content'") : 1,
        'lft' => 0, 'rgt' => 0, 'level' => 1, 'path' => $alias, 'extension' => 'com_content', 'title' => $title,
        'alias' => $alias, 'note' => '', 'description' => $description, 'published' => $published, 'access' => $access,
        'params' => '{"category_layout":"","image":"","image_alt":""}', 'metadesc' => '', 'metakey' => '',
        'metadata' => '{"author":"","robots":""}', 'created_user_id' => $user, 'created_time' => $now,
        'modified_user_id' => $user, 'modified_time' => $now, 'hits' => 0, 'language' => $language, 'version' => 1,
    ]);
    $rebuild('#__categories');
};

$addMenuItem = function ($title, $alias, $menu, $parent, $target, $type, $published, $access, $language, $home, $params) use ($db, $id, $insert, $rebuild) {
    [$kind, $ref] = $target;
    $link = match ($kind) {
        'article' => 'index.php?option=com_content&view=article&id=' . $id('#__content', $ref),
        'blog' => 'index.php?option=com_content&view=category&layout=blog&id=' . $id('#__categories', $ref, " AND extension = 'com_content'"),
        'list' => 'index.php?option=com_content&view=category&id=' . $id('#__categories', $ref, " AND extension = 'com_content'"),
        'featured' => 'index.php?option=com_content&view=featured',
        default => $ref,
    };
    $component = $type === 'component'
        ? (int) $db->setQuery("SELECT extension_id FROM #__extensions WHERE type = 'component' AND element = 'com_content'")->loadResult()
        : 0;
    $insert('#__menu', [
        'menutype' => $menu, 'title' => $title, 'alias' => $alias, 'note' => '', 'path' => $alias, 'link' => $link,
        'type' => $type, 'published' => $published,
        'parent_id' => $parent ? $id('#__menu', $parent, ' AND menutype = ' . $db->quote($menu)) : 1,
        'level' => 1, 'component_id' => $component, 'browserNav' => 0, 'access' => $access, 'img' => '',
        'template_style_id' => 0, 'params' => $params, 'lft' => 0, 'rgt' => 0, 'home' => $home,
        'language' => $language, 'client_id' => 0,
    ]);
    $rebuild('#__menu');
};

// Articles are saved by com_content's ArticleModel, as the article form saves them: with their asset, workflow stage,
// featured row and content plugins. The model needs the administrator application, with the Super User logged in.
$articleModel = function () use ($user) {
    static $app;
    if (!$app) {
        $_SERVER['HTTP_HOST'] ??= 'localhost';
        $container = \Joomla\CMS\Factory::getContainer();
        $container->alias(\Joomla\Session\SessionInterface::class, 'session.cli')
            ->alias(\Joomla\CMS\Session\Session::class, 'session.cli')
            ->alias(\Joomla\Session\Session::class, 'session.cli')
            ->alias('session', 'session.cli');
        $app = $container->get(\Joomla\CMS\Application\AdministratorApplication::class);
        \Joomla\CMS\Factory::$application = $app;
        // What the application's execute() does first: the extensions' namespaces and the behaviour plugins
        // (versions, tags).
        $app->createExtensionNamespaceMap();
        // Set by Joomla when it runs a component; the article model's form needs them.
        define('JPATH_COMPONENT', JPATH_ADMINISTRATOR . '/components/com_content');
        define('JPATH_COMPONENT_ADMINISTRATOR', JPATH_ADMINISTRATOR . '/components/com_content');
        define('JPATH_COMPONENT_SITE', JPATH_SITE . '/components/com_content');
        \Joomla\CMS\Plugin\PluginHelper::importPlugin('behaviour', null, true, $app->getDispatcher());
        $app->loadIdentity($container->get(\Joomla\CMS\User\UserFactoryInterface::class)->loadUserById($user));
    }
    return $app->bootComponent('com_content')->getMVCFactory()->createModel('Article', 'Administrator', ['ignore_request' => true]);
};

$addArticle = function ($title, $alias, $text, $category, $featured, $language) use ($id, $articleModel) {
    $model = $articleModel();
    $saved = $model->save([
        'id' => 0, 'title' => $title, 'alias' => $alias, 'articletext' => $text,
        'catid' => $id('#__categories', $category, " AND extension = 'com_content'"), 'state' => 1,
        'featured' => $featured, 'language' => $language, 'access' => 1,
    ]);
    if (!$saved) {
        throw new RuntimeException("Article $title: " . $model->getError());
    }
};
